import React, { useState } from 'react'
import './App.css'

function App() {
  const [projects, setProjects] = useState([
    { titre: 'Portfolio', description: 'Site personnel pour présenter mes projets.' },
    { titre: 'ToDo App', description: 'Application de gestion de tâches avec React.' }
  ])

  const [titre, setTitre] = useState('')
  const [description, setDescription] = useState('')

  const handleSubmit = (e) => {
    e.preventDefault()
    if (!titre || !description) return
    setProjects([...projects, { titre, description }])
    setTitre('')
    setDescription('')
  }

  return (
    <div className="container">
      <section className="profile">
        <img src="img/photo.jpg" alt="Moi" className="avatar" />
        <h1>ALLA Mohamed</h1>
        <p>Développeur passionné par le web et les nouvelles technologies</p>
      </section>

      <section className="projects">
        <h2>Mes Projets</h2>
        <ul>
          {projects.map((projet, index) => (
            <li key={index} className="project-item">
              <strong>{projet.titre}</strong> – {projet.description}
            </li>
          ))}
        </ul>
      </section>

      <section className="add-project">
        <h2>Ajouter un projet</h2>
        <form onSubmit={handleSubmit} className="form">
          <input
            type="text"
            placeholder="Titre"
            value={titre}
            onChange={(e) => setTitre(e.target.value)}
            className="input"
          />
          <textarea
            placeholder="Description"
            value={description}
            onChange={(e) => setDescription(e.target.value)}
            className="textarea"
          ></textarea>
          <button type="submit" className="button">Ajouter</button>
        </form>
      </section>
    </div>
  )
}

export default App
